using Microsoft.ML;
using Microsoft.ML.Data;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<MLContext>(_ => new MLContext(seed: 42));
builder.Services.AddSingleton<ChurnModelService>();

var app = builder.Build();

// Train the model on startup so prediction is available immediately
var modelService = app.Services.GetRequiredService<ChurnModelService>();
modelService.Train();

app.MapGet("/", () => "Churn Predictor API — POST /predict or POST /train");

app.MapPost("/train", (ChurnModelService svc) =>
{
    var metrics = svc.Train();
    return Results.Ok(new
    {
        metrics.Accuracy,
        metrics.AreaUnderRocCurve,
        metrics.F1Score,
        metrics.PositiveRecall,
        metrics.PositivePrecision,
    });
});

app.MapPost("/predict", (CustomerInput input, ChurnModelService svc) =>
{
    var result = svc.Predict(input);
    return Results.Ok(new
    {
        Churned = result.PredictedLabel,
        Probability = result.Probability,
        Score = result.Score,
    });
});

app.Run();

// --- Data models ---

public class CustomerInput
{
    [LoadColumn(0)] public float Age { get; set; }
    [LoadColumn(1)] public float Income { get; set; }
    [LoadColumn(2)] public string Region { get; set; } = "";
    [LoadColumn(3)] public float PurchaseHistory { get; set; }
    [LoadColumn(4), ColumnName("Label")] public bool Churned { get; set; }
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")] public bool PredictedLabel { get; set; }
    public float Probability { get; set; }
    public float Score { get; set; }
}

// --- Model service ---

public class ChurnModelService
{
    private readonly MLContext _ml;
    private readonly string _dataPath;
    private ITransformer? _model;
    private PredictionEngine<CustomerInput, ChurnPrediction>? _engine;
    private readonly object _lock = new();

    public ChurnModelService(MLContext ml)
    {
        _ml = ml;
        _dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
    }

    public CalibratedBinaryClassificationMetrics Train()
    {
        var data = _ml.Data.LoadFromTextFile<CustomerInput>(
            _dataPath, hasHeader: true, separatorChar: ',');

        var split = _ml.Data.TrainTestSplit(data, testFraction: 0.2);

        var pipeline = _ml.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerInput.Region))
            .Append(_ml.Transforms.Concatenate("Features",
                nameof(CustomerInput.Age),
                nameof(CustomerInput.Income),
                "RegionEncoded",
                nameof(CustomerInput.PurchaseHistory)))
            .Append(_ml.Transforms.NormalizeMinMax("Features"))
            .Append(_ml.Transforms.Conversion.MapValueToKey("Label", nameof(CustomerInput.Churned)))
            .Append(_ml.BinaryClassification.Trainers.SdcaLogisticRegression())
            .Append(_ml.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        var model = pipeline.Fit(split.TrainSet);
        var predictions = model.Transform(split.TestSet);
        var metrics = _ml.BinaryClassification.Evaluate(predictions);

        Console.WriteLine($"[ChurnModel] AUC={metrics.AreaUnderRocCurve:F4}  F1={metrics.F1Score:F4}  Accuracy={metrics.Accuracy:F4}");

        lock (_lock)
        {
            _model = model;
            _engine = _ml.Model.CreatePredictionEngine<CustomerInput, ChurnPrediction>(_model);
        }

        return metrics;
    }

    public ChurnPrediction Predict(CustomerInput input)
    {
        lock (_lock)
        {
            if (_engine is null)
                throw new InvalidOperationException("Model not trained. Call /train first.");
            return _engine.Predict(input);
        }
    }
}

