public CalibratedBinaryClassificationMetrics Train()
{
    var data = _ml.Data.LoadFromTextFile<CustomerInput>(
        _dataPath, hasHeader: true, separatorChar: ',');

    var pipeline = _ml.Transforms.Conversion.MapValue("Label",
            new Dictionary<string, bool> { ["Yes"] = true, ["No"] = false },
            inputColumnName: nameof(CustomerInput.Churned))
        .Append(_ml.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerInput.Region)))
        .Append(_ml.Transforms.Concatenate("Features",
            nameof(CustomerInput.Age),
            nameof(CustomerInput.Income),
            "RegionEncoded",
            nameof(CustomerInput.PurchaseHistory)))
        .Append(_ml.Transforms.NormalizeMinMax("Features"))
        .Append(_ml.BinaryClassification.Trainers.SdcaLogisticRegression());

    // Use train/test split when data is large enough; otherwise train and evaluate on full set
    var rowCount = (int)data.GetColumn<float>(nameof(CustomerInput.Age)).Count();
    ITransformer model;
    IDataView evalData;

    if (rowCount >= 20)
    {
        var split = _ml.Data.TrainTestSplit(data, testFraction: 0.2);
        model = pipeline.Fit(split.TrainSet);
        evalData = model.Transform(split.TestSet);
    }
    else
    {
        Console.WriteLine($"[ChurnModel] Small dataset ({rowCount} rows) — evaluating on training data.");
        model = pipeline.Fit(data);
        evalData = model.Transform(data);
    }

    var metrics = _ml.BinaryClassification.Evaluate(evalData);
    Console.WriteLine($"[ChurnModel] AUC={metrics.AreaUnderRocCurve:F4}  F1={metrics.F1Score:F4}  Accuracy={metrics.Accuracy:F4}");

    lock (_lock)
    {
        _model = model;
        _engine = _ml.Model.CreatePredictionEngine<CustomerInput, ChurnPrediction>(_model);
    }

    return metrics;
}

